/// <summary>
/// pickup advice report controller
/// </summary>
public class METPickupAdviceReportController extends SRSReportRunController
{
}

Method.Source:
/// <summary>Constuct new object</summary>
/// <returns>New Controller Object</returns>
public static METPickupAdviceReportController construct()
{
    return new METPickupAdviceReportController();
}

/// <summary>
/// The main method of the batch job.
/// </summary>
/// <param name = "_args">The arguments passed by the caller object.</param>
public static void main(Args _args)
{
    METPickupAdviceReportContract   contract;

    METPickupAdviceReportController controller = METPickupAdviceReportController::construct();
    controller.parmReportName(ssrsReportStr(METPickUpAdvicesReport, Report));
    controller.parmArgs(_args);
    contract = controller.getDataContractObject() as METPickupAdviceReportContract;
    controller.startOperation();
}
